  typescript: ['domain_ts.ts', `export function loadTs(id: string) { return id; }\n`,
    'service_ts.ts', `import { loadTs } from './domain_ts.js';\nexport function serveTs(id: string) { return loadTs(id); }\n`, 'loadTs'],
